        {/*
          4-column grid, 4 rows — each cell a different size:

          Row 1 (380px):  [CodeBlock — 2col]  [ChatMessages — 2col]
          Row 2 (320px):  [CardStack — 1col]  [EncryptedText — 1col]  [Typewriter — 2col]
