              <EncryptedText
                text="Build the future"
                trigger="viewport"
                loop
                loopDelay={3000}
                speed={45}
                revealDelay={400}
                className="text-base font-medium text-white/50"
              />
              <EncryptedText
                text="component by component"
                trigger="viewport"
