export default RealTimeCursors;

"use client";

import * as React from "react";
import { motion, AnimatePresence } from "framer-motion";

// ── Types ─────────────────────────────────────────────────────────────────────

export type CodeLanguage =
  | "plain"
  | "js"
  | "ts"
  | "jsx"
  | "tsx"
  | "css"
  | "json"
  | "html";

export type HeaderProps = {
  enabled?: boolean;
  showDots?: boolean;
  background?: string;
  title?: string;
  font?: React.CSSProperties;
  titleColor?: string;
  copy?: CopyProps;
};

export type CopyProps = {
  enabled?: boolean;
  label?: string;
  copiedLabel?: string;
  copiedDurationMs?: number;
  color?: string;
  accentColor?: string;
};

export type CodeAreaProps = {
  showLineNumbers?: boolean;
  wrap?: boolean;
  padding?: number;
  background?: string;
  selectionColor?: string;
  textColor?: string;
  subtleTextColor?: string;
  font?: React.CSSProperties;
