function HighlightedLine({
  tokens,
  baseColor,
  isDark,
}: {
  tokens: Token[];
  baseColor: string;
  isDark: boolean;
}) {
  return (
    <>
      {tokens.map((tok, idx) => (
        <span
          key={idx}
          style={{ color: tokenColor(tok.t, baseColor, isDark) }}
        >
          {tok.v.length > 0 ? tok.v : " "}
        </span>
      ))}
    </>
  );
}

