export function ChatMessages({
  messages = DEFAULT_MESSAGES,
  autoPlay = true,
  autoPlayDelay = 1800,
  typingDuration = 1400,
  showReplay = true,
  interactive = false,
  className,
}: ChatMessagesProps) {
  const [visibleCount, setVisibleCount] = useState(autoPlay ? 0 : messages.length);
  const [isTyping, setIsTyping] = useState(false);
  const [inputValue, setInputValue] = useState("");
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>(messages);
  const scrollRef = useRef<HTMLDivElement>(null);
  const isAutoPlaying = useRef(false);

  const scrollToBottom = useCallback(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: "smooth",
      });
    }
  }, []);

  const revealNext = useCallback(
    async (index: number) => {
      if (index >= chatMessages.length) {
        isAutoPlaying.current = false;
        return;
      }

      const message = chatMessages[index];

      if (message.sender === "assistant") {
        setIsTyping(true);
        await new Promise((r) => setTimeout(r, typingDuration));
        setIsTyping(false);
      }

      setVisibleCount(index + 1);
      await new Promise((r) => setTimeout(r, 100));
      scrollToBottom();

      await new Promise((r) => setTimeout(r, autoPlayDelay - (message.sender === "assistant" ? typingDuration : 0) - 100));

      if (isAutoPlaying.current) {
        revealNext(index + 1);
      }
    },
    [chatMessages, autoPlayDelay, typingDuration, scrollToBottom],
  );

  const startAutoPlay = useCallback(() => {
    if (autoPlay && visibleCount === 0) {
      isAutoPlaying.current = true;
      revealNext(0);
    }
  }, [autoPlay, visibleCount, revealNext]);

  const replay = useCallback(() => {
    setVisibleCount(0);
    setChatMessages(messages);
    isAutoPlaying.current = true;
    setTimeout(() => revealNext(0), 100);
  }, [messages, revealNext]);

  useEffect(() => {
    setChatMessages(messages);
    if (autoPlay) {
      setVisibleCount(0);
      isAutoPlaying.current = true;
      const timer = setTimeout(() => revealNext(0), 500);
      return () => {
        clearTimeout(timer);
        isAutoPlaying.current = false;
      };
    } else {
      setVisibleCount(messages.length);
    }
  }, [messages, autoPlay, revealNext]);

  useEffect(() => {
    scrollToBottom();
  }, [visibleCount, isTyping, scrollToBottom]);

  const handleSend = useCallback(() => {
    if (!inputValue.trim() || !interactive) return;

    const newMessage: ChatMessage = {
      id: `user-${Date.now()}`,
      sender: "user",
      content: inputValue.trim(),
    };

    setChatMessages((prev) => [...prev, newMessage]);
    setInputValue("");
    setVisibleCount((prev) => prev + 1);

    setTimeout(() => {
      const assistantReply: ChatMessage = {
        id: `assistant-${Date.now()}`,
        sender: "assistant",
        content: "That's a great question! Let me help you explore the best options for your use case.",
      };
      setChatMessages((prev) => [...prev, assistantReply]);
      setVisibleCount((prev) => prev + 1);
    }, typingDuration + 500);
  }, [inputValue, interactive, typingDuration]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div
      className={cn(
        "relative flex flex-col overflow-hidden rounded-2xl border border-white/10 bg-gradient-to-b from-zinc-900 to-zinc-950 shadow-[0_24px_64px_-16px_rgba(0,0,0,0.5)]",
        className,
      )}
    >
      {/* Header */}
      <div className="flex items-center justify-between border-b border-white/5 px-4 py-3">
        <div className="flex items-center gap-2">
          <div className="flex h-8 w-8 items-center justify-center rounded-full bg-gradient-to-br from-indigo-500 to-violet-600">
            <Sparkles className="size-4 text-white" />
          </div>
          <div>
            <h3 className="text-sm font-medium text-white">Nexus AI</h3>
            <p className="text-xs text-white/40">Always here to help</p>
          </div>
        </div>
        {showReplay && (
          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={replay}
            aria-label="Replay conversation"
            className="flex items-center gap-1.5 rounded-lg bg-white/5 px-3 py-1.5 text-xs text-white/60 transition-colors hover:bg-white/10 hover:text-white"
          >
            <RotateCcw className="size-3.5" />
            Replay
          </motion.button>
        )}
      </div>

      {/* Messages */}
      <div
        ref={scrollRef}
        role="log"
        aria-label="Chat messages"
        aria-live="polite"
        className="flex-1 space-y-3 overflow-y-auto p-4 scrollbar-thin scrollbar-thumb-white/10 scrollbar-track-transparent"
      >
        {chatMessages.slice(0, visibleCount).map((message, i) => (
          <MessageBubble
            key={message.id}
            message={message}
            isLast={i === visibleCount - 1}
          />
        ))}

        <AnimatePresence>
          {isTyping && <TypingIndicator />}
        </AnimatePresence>
      </div>

      {/* Input */}
      <div className="border-t border-white/5 p-3">
        <div className="flex items-center gap-2 rounded-xl border border-white/10 bg-zinc-800/50 px-4 py-2 backdrop-blur-sm focus-within:border-white/20 focus-within:bg-zinc-800/70">
          <input
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={handleKeyDown}
            disabled={!interactive}
            placeholder={interactive ? "Ask Nexus AI..." : "Demo mode - replay to watch again"}
            aria-label={interactive ? "Type your message" : "Chat input (demo mode)"}
            className="flex-1 bg-transparent text-sm text-white outline-none placeholder:text-white/30 disabled:cursor-not-allowed"
          />
          <motion.button
            whileHover={{ scale: 1.08 }}
            whileTap={{ scale: 0.92 }}
            onClick={handleSend}
            disabled={!interactive || !inputValue.trim()}
            aria-label="Send message"
            className={cn(
              "flex h-8 w-8 items-center justify-center rounded-lg transition-colors",
              interactive && inputValue.trim()
                ? "bg-indigo-600 text-white hover:bg-indigo-500"
                : "bg-white/5 text-white/30",
            )}
          >
            <Send className="size-4" />
          </motion.button>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { motion, AnimatePresence, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface CardData {
  id: string;
  content: string;
  name: string;
  designation: string;
  avatarUrl?: string;
  initials?: string;
  company?: string;
  companyLogoUrl?: string;
}

export interface CardStackRotatorProps {
  cards: CardData[];
  rotationInterval?: number;
  maxVisible?: number;
  stackOffset?: number;
  scaleStep?: number;
  cardWidth?: string;
  cardHeight?: string;
  cardBackground?: string;
  cardBorderColor?: string;
  textColor?: string;
  mutedColor?: string;
  highlightBackground?: string;
  highlightTextColor?: string;
  contentFontSize?: string;
  nameFontSize?: string;
  designationFontSize?: string;
  borderRadius?: string;
  shadowIntensity?: number;
  pauseOnHover?: boolean;
  direction?: "forward" | "backward";
  className?: string;
}

// ── Highlight parser ───────────────────────────────────────────────────────────

function parseHighlights(text: string): React.ReactNode[] {
  const parts: React.ReactNode[] = [];
  const segments = text.split(/(\*\*[^*]+\*\*)/);
  let key = 0;
  for (const seg of segments) {
    const match = seg.match(/^\*\*([^*]+)\*\*$/);
    if (match) {
      parts.push(
        <mark
          key={key++}
          style={{
            background: "rgba(129,140,248,0.18)",
            color: "#a5b4fc",
            borderRadius: "4px",
            padding: "0 2px",
          }}
        >
          {match[1]}
        </mark>,
      );
    } else if (seg) {
      parts.push(seg);
    }
  }
  return parts;
}

// ── Avatar ─────────────────────────────────────────────────────────────────────

interface AvatarProps {
  src?: string;
  initials?: string;
  size?: number;
  background?: string;
  textColor?: string;
}

function Avatar({ src, initials, size = 40, background, textColor }: AvatarProps) {
  if (src) {
    return (
      <img
        src={src}
        alt={initials ?? "avatar"}
        className="rounded-full object-cover"
        style={{ width: size, height: size }}
      />
    );
  }
  return (
    <div
      className="flex items-center justify-center rounded-full"
      style={{
        width: size,
        height: size,
        background: background ?? "rgba(129,140,248,0.2)",
        color: textColor ?? "#a5b4fc",
        fontSize: size * 0.36,
        fontWeight: 600,
      }}
    >
      {initials ?? "?"}
    </div>
  );
}

// ── Spring config ──────────────────────────────────────────────────────────────

const SPRING_ENTER = { type: "spring" as const, stiffness: 280, damping: 30, mass: 1 };
const SPRING_EXIT = { type: "spring" as const, stiffness: 320, damping: 32, mass: 0.8 };

// ── Main component ─────────────────────────────────────────────────────────────

export function CardStackRotator({
  cards,
  rotationInterval = 3000,
  maxVisible = 4,
  stackOffset = 16,
  scaleStep = 0.04,
  cardWidth = "100%",
  cardHeight = "380px",
  cardBackground = "#111113",
  cardBorderColor = "rgba(255,255,255,0.07)",
  textColor = "#fafafa",
  mutedColor = "rgba(250,250,250,0.45)",
  highlightTextColor = "#a5b4fc",
  contentFontSize = "15px",
  nameFontSize = "15px",
  designationFontSize = "12px",
  borderRadius = "16px",
  shadowIntensity = 0.55,
  pauseOnHover = true,
  className,
}: CardStackRotatorProps) {
  const reduceMotion = useReducedMotion() === true;
  const [frontIndex, setFrontIndex] = React.useState(0);
  const [isPaused, setIsPaused] = React.useState(false);
  const timerRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);

  const totalCards = cards.length;
  const visibleCount = Math.min(maxVisible, totalCards);

  // Visible window: front card at position 0, subsequent cards behind
  const visibleCards = React.useMemo(() => {
    if (!totalCards) return [];
    const front = frontIndex % totalCards;
    return Array.from({ length: visibleCount }, (_, i) => {
      const cardIdx = (front + i) % totalCards;
      return { card: cards[cardIdx], stackIndex: i };
    });
  }, [cards, frontIndex, visibleCount, totalCards]);

  React.useEffect(() => {
    if (isPaused || reduceMotion) {
      if (timerRef.current) clearTimeout(timerRef.current);
      return;
    }
    const id = setTimeout(() => {
      setFrontIndex((prev) => (prev + 1) % totalCards);
    }, rotationInterval);
    timerRef.current = id;
    return () => clearTimeout(id);
  }, [isPaused, reduceMotion, frontIndex, rotationInterval, totalCards]);

  if (!totalCards) return null;

  const shadowBlur = 20 + shadowIntensity * 30;
  const shadowOpacity = 0.12 + shadowIntensity * 0.28;

  return (
    <div
      className={cn("relative flex items-center justify-center", className)}
      style={{ width: cardWidth, height: cardHeight }}
      onMouseEnter={() => pauseOnHover && setIsPaused(true)}
      onMouseLeave={() => pauseOnHover && setIsPaused(false)}
    >
      <AnimatePresence mode="popLayout">
        {visibleCards.map(({ card, stackIndex }) => {
          const yOffset = stackIndex * stackOffset;
          const scale = 1 - stackIndex * scaleStep;
          const zBase = visibleCount - stackIndex;

          return (
            <motion.div
              key={card.id}
              layout
              // Initial state for cards entering the stack
              initial={{
                y: yOffset + 56,
                scale: scale - 0.07,
                opacity: 0,
                zIndex: zBase,
              }}
              // Animate to final stacked position
              animate={{
                y: yOffset,
                scale,
                opacity: 1,
                zIndex: zBase,
                transition: {
                  ...SPRING_ENTER,
                  delay: stackIndex * 0.04, // slight cascade for depth feel
                },
              }}
              // Exit animation — front card exits upward
              exit={{
                y: yOffset - 75,
                scale: 1.05,
                opacity: 0,
                zIndex: 0,
                transition: {
                  ...SPRING_EXIT,
                },
              }}
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                width: cardWidth,
                height: cardHeight,
                transformOrigin: "center bottom",
                willChange: "transform, opacity",
              }}
            >
              <div
                className="flex h-full flex-col justify-between rounded-2xl p-6"
                style={{
                  background: cardBackground,
                  border: `1px solid ${cardBorderColor}`,
                  borderRadius,
                  boxShadow: `0 ${shadowBlur}px ${shadowBlur * 1.5}px rgba(0,0,0,${shadowOpacity}), 0 2px 8px rgba(0,0,0,${shadowOpacity * 0.5})`,
                  color: textColor,
                  backfaceVisibility: "hidden",
                }}
              >
                {/* Content */}
                <div
                  style={{
                    fontSize: contentFontSize,
                    color: textColor,
                    lineHeight: 1.65,
                  }}
                >
                  {parseHighlights(card.content)}
                </div>

                {/* Footer */}
                <div className="mt-5 flex items-center gap-3">
                  <Avatar
                    src={card.avatarUrl}
                    initials={
                      card.initials ??
                      card.name
                        .split(" ")
                        .map((n) => n[0])
                        .join("")
                        .slice(0, 2)
                        .toUpperCase()
                    }
                    size={40}
                    background="rgba(129,140,248,0.15)"
                    textColor={highlightTextColor}
                  />
                  <div>
                    <p
                      style={{
                        fontSize: nameFontSize,
                        color: textColor,
                        fontWeight: 600,
                      }}
                    >
                      {card.name}
                    </p>
                    <p
                      style={{
                        fontSize: designationFontSize,
                        color: mutedColor,
                        marginTop: 2,
                      }}
                    >
                      {card.designation}
                      {card.company ? ` · ${card.company}` : ""}
                    </p>
                  </div>
                </div>
              </div>
            </motion.div>
          );
        })}
      </AnimatePresence>
    </div>
  );
}

"use client";

import * as React from "react";
import { useInView, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";

const DEFAULT_CHARSET =
  "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789@#$%^&*!<>/|[]{}~=-_+:.";

function pickRandom(chars: string): string {
  return chars[Math.floor(Math.random() * chars.length)] ?? chars[0]!;
}

function isPreserved(c: string): boolean {
  return c === " " || c === "\n" || c === "\t";
}

type CharState = { char: string; locked: boolean };

function initStates(text: string, charset: string): CharState[] {
  return Array.from(text).map((c) =>
    isPreserved(c) ? { char: c, locked: true } : { char: pickRandom(charset), locked: false },
  );
}

export type EncryptedTextTrigger = "load" | "hover" | "viewport" | "click";

export interface EncryptedTextProps {
  text: string;
  className?: string;
  /** ms between each character locking in. Default: 50 */
  speed?: number;
  /** ms between gibberish shuffle ticks. Default: 35 */
  shuffleSpeed?: number;
  /** ms delay before animation starts. Default: 0 */
  revealDelay?: number;
  /** Charset for the gibberish phase. */
  characters?: string;
  /** Shuffle cycles before first character locks in. Default: 8 */
  iterations?: number;
  /** What triggers the reveal. Default: "load" */
  trigger?: EncryptedTextTrigger;
  /** Loop the animation after completion. Default: false */
  loop?: boolean;
  /** ms to wait before replaying when loop=true. Default: 2000 */
  loopDelay?: number;
  /** Polymorphic element. Default: "span" */
  as?: "span" | "p" | "h1" | "h2" | "h3" | "div";
  /** Called once every character has locked in. */
  onComplete?: () => void;
  /**ClassName applied to scrambling (unlocked) characters. Defaults to primary/cyan glow. */
  scrambleClassName?: string;
}

export function EncryptedText({
  text,
  className,
  speed = 50,
  shuffleSpeed = 35,
  revealDelay = 0,
  characters = DEFAULT_CHARSET,
  iterations = 8,
  trigger = "load",
  loop = false,
  loopDelay = 2000,
  as: Tag = "span",
  onComplete,
  scrambleClassName,
}: EncryptedTextProps) {
  const reduceMotion = useReducedMotion();
  const rootRef = React.useRef<HTMLElement>(null);
  const isInView = useInView(rootRef as React.RefObject<Element>, {
    once: !loop,
    amount: 0.3,
  });

  const [states, setStates] = React.useState<CharState[]>(() =>
    Array.from(text).map((c) => ({ char: c, locked: true }))
  );

  // Always-current config refs — read inside effects without stale closure risk
  const cfg = React.useRef({ text, characters, speed, shuffleSpeed, iterations, loop, loopDelay, onComplete });
  cfg.current = { text, characters, speed, shuffleSpeed, iterations, loop, loopDelay, onComplete };

  // Incrementing this triggers one animation run
  const [cycle, setCycle] = React.useState(0);

  // play() is the single entry point for all trigger modes
  const play = React.useCallback(() => setCycle((n) => n + 1), []);

  // Core animation — isolated per cycle so cleanup fully cancels the previous run
  React.useEffect(() => {
    if (cycle === 0) return;

    const { text: t, characters: ch, speed: sp, shuffleSpeed: ss,
            iterations: it, loop: lp, loopDelay: ld, onComplete: cb } = cfg.current;

    if (reduceMotion) {
      setStates(Array.from(t).map((c) => ({ char: c, locked: true })));
      cb?.();
      return;
    }

    let dead = false;
    let revealIdx = 0;

    setStates(initStates(t, ch));

    // Phase 1 — fast shuffle of all unrevealed characters
    const shuffleTimer = setInterval(() => {
      if (dead) return;
      setStates((prev) =>
        prev.map((s) => (s.locked ? s : { char: pickRandom(ch), locked: false })),
      );
    }, ss);

    // Phase 2 — after warmup, lock one character per tick
    let revealTimer: ReturnType<typeof setInterval> | null = null;
    let loopTimer: ReturnType<typeof setTimeout> | null = null;

    const warmupTimer = setTimeout(() => {
      if (dead) return;

      revealTimer = setInterval(() => {
        if (dead) return;

        if (revealIdx >= t.length) {
          clearInterval(revealTimer!);
          clearInterval(shuffleTimer);
          if (!dead) {
            setStates(Array.from(t).map((c) => ({ char: c, locked: true })));
            cb?.();
            if (lp) {
              loopTimer = setTimeout(() => { if (!dead) setCycle((n) => n + 1); }, ld);
            }
          }
          return;
        }

        const idx = revealIdx++;
        setStates((prev) => {
          const next = [...prev];
          next[idx] = { char: t[idx]!, locked: true };
          return next;
        });
      }, sp);
    }, it * ss);

    return () => {
      dead = true;
      clearInterval(shuffleTimer);
      clearTimeout(warmupTimer);
      if (revealTimer) clearInterval(revealTimer);
      if (loopTimer) clearTimeout(loopTimer);
    };
  }, [cycle, reduceMotion]);

  // Trigger: load — schedule play() after revealDelay
  React.useEffect(() => {
    if (trigger !== "load") return;
    const t = setTimeout(play, revealDelay);
    return () => clearTimeout(t);
  }, [trigger, revealDelay, play]);

  // Trigger: viewport — play() once the element enters the viewport
  React.useEffect(() => {
    if (trigger !== "viewport" || !isInView) return;
    const t = setTimeout(play, revealDelay);
    return () => clearTimeout(t);
  }, [trigger, isInView, revealDelay, play]);

  // Trigger: hover / click
  const handleInteraction = React.useCallback(() => {
    setTimeout(play, revealDelay);
  }, [play, revealDelay]);

  const interactionProps: React.HTMLAttributes<HTMLElement> = {};
  if (trigger === "hover") {
    interactionProps.onMouseEnter = handleInteraction;
  } else if (trigger === "click") {
    interactionProps.onClick = handleInteraction;
    interactionProps.onKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === "Enter" || e.key === " ") handleInteraction();
    };
  }

  return (
    <Tag
      ref={rootRef as React.RefObject<never>}
      aria-label={text}
      role={trigger === "click" ? "button" : undefined}
      tabIndex={trigger === "click" ? 0 : undefined}
      className={cn(
        "font-mono whitespace-pre-wrap",
        trigger === "click" && "cursor-pointer select-none",
        className,
      )}
      {...interactionProps}
    >
      {states.map((s, i) => (
        <span
          key={i}
          aria-hidden="true"
          className={cn(
            "inline-block transition-colors duration-75",
            s.locked ? "text-current" : (scrambleClassName ?? "text-primary dark:text-cyan-400"),
          )}
          style={
            !s.locked
              ? { filter: "drop-shadow(0 0 5px currentColor)", opacity: 0.85 }
              : undefined
          }
        >
          {s.char}
        </span>
      ))}
    </Tag>
  );
}

"use client";

import * as React from "react";
import { motion, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";

type TypewriterTag = "h1" | "h2" | "p" | "span" | "div";
type TypewriterText = string | string[];
type TypewriterPhase = "typing" | "pausing" | "deleting" | "done";

export type TypewriterEffectProps = {
  text: TypewriterText;
  typingSpeed?: number;
  deletingSpeed?: number;
  delay?: number;
  pauseDuration?: number;
  loop?: boolean;
  showCursor?: boolean;
  cursorClassName?: string;
  className?: string;
  as?: TypewriterTag;
  onComplete?: () => void;
};

const clamp = (value: number, min: number) => Math.max(min, value);

export function TypewriterEffect({
  text,
  typingSpeed = 65,
  deletingSpeed = 42,
  delay = 0,
  pauseDuration = 1200,
  loop = false,
  showCursor = true,
  cursorClassName,
  className,
  as = "span",
  onComplete,
}: TypewriterEffectProps) {
  const reduceMotion = useReducedMotion() === true;
  const Tag = as;

  const textList = React.useMemo(() => {
    const list = Array.isArray(text) ? text : [text];
    const normalized = list.map((item) => item ?? "").filter((item) => item.length > 0);
    return normalized.length ? normalized : [""];
  }, [text]);

  const [phase, setPhase] = React.useState<TypewriterPhase>(reduceMotion ? "done" : "typing");
  const [textIndex, setTextIndex] = React.useState(0);
  const [charIndex, setCharIndex] = React.useState(reduceMotion ? textList[0].length : 0);
  const completionFiredRef = React.useRef(false);

  const currentText = textList[textIndex] ?? "";
  const visibleText = currentText.slice(0, charIndex);
  const hasMultipleTexts = textList.length > 1;
  const canDelete = deletingSpeed > 0;
  const shouldLoop = loop === true;
  const longestChars = React.useMemo(
    () => textList.reduce((max, item) => Math.max(max, item.length), 0),
    [textList],
  );

  React.useEffect(() => {
    completionFiredRef.current = false;
    if (reduceMotion) {
      setTextIndex(Math.max(0, textList.length - 1));
      setCharIndex(textList[Math.max(0, textList.length - 1)]?.length ?? 0);
      setPhase("done");
      onComplete?.();
      return;
    }
    setTextIndex(0);
    setCharIndex(0);
    setPhase("typing");
  }, [reduceMotion, textList, onComplete]);

  React.useEffect(() => {
    if (reduceMotion || phase === "done") return;

    const typeMs = clamp(typingSpeed, 10);
    const deleteMs = clamp(deletingSpeed, 10);
    const waitMs = clamp(pauseDuration, 0);
    const initialDelay = clamp(delay, 0);

    const timer = window.setTimeout(() => {
      if (phase === "typing") {
        if (charIndex < currentText.length) {
          setCharIndex((v) => v + 1);
          return;
        }
        setPhase("pausing");
        return;
      }

      if (phase === "pausing") {
        const isLastText = textIndex === textList.length - 1;
        const hasNextText = !isLastText || shouldLoop;

        if (!hasNextText) {
          if (!completionFiredRef.current) {
            completionFiredRef.current = true;
            onComplete?.();
          }
          setPhase("done");
          return;
        }

        if (!canDelete) {
          const nextIndex = isLastText ? 0 : textIndex + 1;
          setTextIndex(nextIndex);
          setCharIndex(0);
          if (isLastText && shouldLoop) onComplete?.();
          setPhase("typing");
          return;
        }

        setPhase("deleting");
        return;
      }

      if (phase === "deleting") {
        if (charIndex > 0) {
          setCharIndex((v) => v - 1);
          return;
        }
        const isLastText = textIndex === textList.length - 1;
        const nextIndex = isLastText ? 0 : textIndex + 1;
        if (isLastText) onComplete?.();
        setTextIndex(nextIndex);
        setPhase("typing");
      }
    }, phase === "typing" ? (charIndex === 0 ? initialDelay : typeMs) : phase === "pausing" ? waitMs : deleteMs);

    return () => window.clearTimeout(timer);
  }, [
    canDelete,
    charIndex,
    currentText.length,
    delay,
    deletingSpeed,
    onComplete,
    pauseDuration,
    phase,
    reduceMotion,
    shouldLoop,
    textIndex,
    textList.length,
    typingSpeed,
  ]);

  return (
    <Tag className={cn("relative inline-flex items-baseline whitespace-pre-wrap", className)}>
      <span className="sr-only">{Array.isArray(text) ? text.join(" ") : text}</span>
      <span
        aria-hidden
        className="inline-block whitespace-pre-wrap"
        style={{ minWidth: hasMultipleTexts ? `${Math.max(1, longestChars)}ch` : undefined }}
      >
        {visibleText}
      </span>
      {showCursor ? (
        <motion.span
          aria-hidden
          className={cn("ml-1 inline-block h-[1em] w-[2px] rounded-sm bg-current align-[-0.08em]", cursorClassName)}
          animate={{ opacity: [1, 0.2, 1] }}
          transition={{ duration: 0.9, repeat: Infinity, ease: "easeInOut" }}
        />
      ) : null}
    </Tag>
  );
}
